'use client'
import { useEffect } from 'react'
import { useRouter } from 'next/navigation'

const LP_CSS = "@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');\n*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}\nhtml{scroll-behavior:smooth;overflow-x:hidden}\nbody{font-family:'Inter',-apple-system,sans-serif;background:#050709;color:#e2e8f0;overflow-x:hidden}\n#bg{position:fixed;inset:0;width:100%;height:100%;z-index:0;pointer-events:none}\n#app{position:relative;z-index:1}\n\n/* \u2550\u2550 NAV \u2550\u2550 */\nnav{position:fixed;top:0;left:0;right:0;z-index:100;padding:14px 40px;display:flex;align-items:center;justify-content:space-between;background:rgba(5,7,9,0.65);backdrop-filter:blur(24px);border-bottom:1px solid rgba(255,255,255,0.07);transition:all .3s}\n\n.logo-link{display:flex;align-items:center;text-decoration:none;cursor:pointer}\n.logo-wordmark{font-size:18px;font-weight:800;color:#e2e8f0;letter-spacing:-.02em}\n.nav-links{display:flex;gap:30px}\n.nav-links a{font-size:14px;font-weight:500;color:rgba(255,255,255,0.5);text-decoration:none;transition:color .2s}\n.nav-links a:hover{color:#e2e8f0}\n.nav-btns{display:flex;align-items:center;gap:12px}\n.btn-ghost{font-size:14px;font-weight:600;color:rgba(255,255,255,0.55);background:none;border:none;cursor:pointer;font-family:inherit;transition:color .2s}\n.btn-ghost:hover{color:#e2e8f0}\n.btn-nav-cta{padding:9px 22px;border-radius:10px;border:none;cursor:pointer;font-family:inherit;font-size:14px;font-weight:700;color:#fff;background:linear-gradient(135deg,#2563eb,#7c3aed);box-shadow:0 4px 16px rgba(99,102,241,0.4);transition:all .15s}\n.btn-nav-cta:hover{transform:translateY(-1px);box-shadow:0 8px 24px rgba(99,102,241,0.55)}\n\n/* \u2550\u2550 HERO \u2550\u2550 */\n.hero{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:120px 32px 0px;text-align:center;position:relative}\n.hero-light{position:absolute;width:700px;height:700px;border-radius:50%;background:radial-gradient(circle,rgba(99,102,241,0.07),transparent 65%);pointer-events:none;transform:translate(-50%,-50%);left:50%;top:50%;transition:left .7s cubic-bezier(.23,1,.32,1),top .7s cubic-bezier(.23,1,.32,1)}\n\n.hero-badge{display:inline-flex;align-items:center;gap:8px;padding:8px 18px;border-radius:100px;background:rgba(255,255,255,0.07);border:1px solid rgba(255,255,255,0.13);font-size:13px;font-weight:600;color:rgba(255,255,255,0.72);margin-bottom:36px;backdrop-filter:blur(16px);animation:fade-up .8s .1s both}\n@keyframes fade-up{from{opacity:0;transform:translateY(-14px)}to{opacity:1;transform:none}}\n.badge-dot{width:7px;height:7px;border-radius:50%;background:#10b981;box-shadow:0 0 8px #10b981,0 0 18px rgba(16,185,129,0.5);animation:dot-g 2s ease-in-out infinite}\n\n@keyframes lp-spin{100%{transform:rotate(360deg)}}\n@keyframes lp-rock{0%,100%{transform:rotate(-4deg) scale(1)}50%{transform:rotate(4deg) scale(1.08)}}\n\n@keyframes dot-g{0%,100%{box-shadow:0 0 8px #10b981,0 0 18px rgba(16,185,129,0.5)}50%{box-shadow:0 0 14px #10b981,0 0 30px rgba(16,185,129,0.7)}}\n\n/* FIX: padding-bottom so descenders (y,g) aren't clipped by gradient mask */\n.hero-title{\n  font-size:clamp(44px,7.5vw,96px);\n  font-weight:900;letter-spacing:-0.045em;line-height:1.12;\n  margin-bottom:26px;width:100%;max-width:1100px;\n  padding-bottom:0.25em;\n  overflow:visible;\n}\n.hero-line{\n  display:block;\n  animation:line-up .9s both;\n  padding-bottom:0.25em;\n  overflow:visible;\n  /* white-space:normal allows wrapping on narrow screens \u2014 nowrap only on desktop */\n  white-space:nowrap;\n}\n@media(max-width:768px){.hero-line{white-space:normal;}}\n.hero-line:nth-child(1){animation-delay:.1s}\n.hero-line:nth-child(2){animation-delay:.2s}\n.hero-line:nth-child(3){animation-delay:.3s}\n@keyframes line-up{from{opacity:0;transform:translateY(50px)}to{opacity:1;transform:none}}\n.g1{background:linear-gradient(135deg,#fff,#c4b5fd 40%,#a78bfa);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}\n.g2{background:linear-gradient(135deg,#fce7f3,#f9a8d4 35%,#f472b6 65%,#ec4899);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}\n.g3{background:linear-gradient(135deg,#bfdbfe,#93c5fd 35%,#60a5fa 65%,#3b82f6);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}\n\n.hero-sub{font-size:clamp(16px,2vw,20px);color:rgba(255,255,255,0.42);max-width:540px;line-height:1.68;margin-bottom:44px;animation:line-up 1s .4s both}\n.hero-btns{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;animation:line-up 1s .55s both}\n.btn-primary{padding:16px 34px;border-radius:14px;border:none;cursor:pointer;font-family:inherit;font-size:16px;font-weight:700;color:#fff;letter-spacing:-.02em;background:linear-gradient(135deg,#2563eb,#7c3aed);background-size:200% 200%;box-shadow:0 8px 32px rgba(99,102,241,0.5),inset 0 0 0 1px rgba(255,255,255,0.1);position:relative;overflow:hidden;animation:btn-shift 5s ease infinite;transition:transform .15s,box-shadow .15s}\n@keyframes btn-shift{0%{background-position:0% 50%}50%{background-position:100% 50%}100%{background-position:0% 50%}}\n.btn-primary::before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent,rgba(255,255,255,0.18),transparent);transform:translateX(-100%);animation:btn-shine 2.8s ease infinite}\n@keyframes btn-shine{0%{transform:translateX(-100%)}55%,100%{transform:translateX(200%)}}\n.btn-primary:hover{transform:translateY(-2px);box-shadow:0 14px 44px rgba(99,102,241,0.65)}\n.btn-sec{padding:16px 34px;border-radius:14px;cursor:pointer;font-family:inherit;border:1px solid rgba(255,255,255,0.15);background:rgba(255,255,255,0.07);color:rgba(255,255,255,0.75);font-size:16px;font-weight:600;backdrop-filter:blur(16px);transition:all .15s;display:flex;align-items:center;gap:9px}\n.btn-sec:hover{background:rgba(255,255,255,0.13);color:#fff}\n.sec-dot{width:8px;height:8px;border-radius:50%;background:#10b981;box-shadow:0 0 8px #10b981;animation:dot-g 2s ease-in-out infinite}\n.scroll-ind{position:absolute;bottom:28px;left:50%;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:6px;color:rgba(255,255,255,0.18);font-size:10px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;animation:bob 2.8s ease-in-out infinite}\n@keyframes bob{0%,100%{transform:translateX(-50%) translateY(0)}50%{transform:translateX(-50%) translateY(9px)}}\n\n/* \u2550\u2550 SHARED \u2550\u2550 */\n.sec-wrap{padding:100px 48px;position:relative}\n.sec-inner{max-width:1200px;margin:0 auto}\n.eyebrow{display:inline-flex;align-items:center;gap:8px;font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#818cf8;margin-bottom:14px}\n.eyebrow::before{content:'';display:block;width:26px;height:1.5px;background:linear-gradient(90deg,#6366f1,transparent)}\n.sec-title{font-size:clamp(30px,4vw,50px);font-weight:800;letter-spacing:-.04em;line-height:1.06;margin-bottom:16px}\n.sec-body{font-size:16px;color:rgba(255,255,255,0.4);line-height:1.75;max-width:500px;margin-bottom:40px}\n.sec-body-c{font-size:16px;color:rgba(255,255,255,0.4);line-height:1.75;max-width:580px;margin:0 auto 48px;text-align:center}\n.rv{opacity:0;transform:translateY(36px);transition:opacity .85s cubic-bezier(.23,1,.32,1),transform .85s cubic-bezier(.23,1,.32,1)}\n.rv.d1{transition-delay:.1s}.rv.d2{transition-delay:.2s}.rv.d3{transition-delay:.3s}\n.rv.visible{opacity:1;transform:none}\n\n/* \u2550\u2550 LIVE CLASSROOM \u2550\u2550 */\n.live-bg{position:absolute;inset:0;background:linear-gradient(180deg,transparent 0%,transparent 48%,rgba(8,10,20,0.82) 58%,rgba(8,10,20,0.88) 80%,transparent 100%);pointer-events:none}\n.cc-glow{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:900px;height:500px;background:radial-gradient(ellipse,rgba(59,130,246,0.1),rgba(99,102,241,0.07) 40%,transparent 70%);animation:gp 4s ease-in-out infinite;pointer-events:none}\n@keyframes gp{0%,100%{opacity:1;transform:translate(-50%,-50%) scale(1)}50%{opacity:.6;transform:translate(-50%,-50%) scale(1.06)}}\n.cc-card{background:rgba(8,12,22,0.88);border:1px solid rgba(255,255,255,0.1);border-radius:20px;overflow:hidden;box-shadow:0 40px 120px rgba(0,0,0,.7),inset 0 0 0 1px rgba(255,255,255,0.05);backdrop-filter:blur(28px);max-width:1000px;margin:0 auto}\n.cc-top{padding:13px 20px;border-bottom:1px solid rgba(255,255,255,0.08);display:flex;align-items:center;justify-content:space-between;background:rgba(255,255,255,0.03)}\n.live-badge{display:flex;align-items:center;gap:7px;font-size:12px;font-weight:700;color:#f87171}\n.live-dot{width:8px;height:8px;border-radius:50%;background:#ef4444;box-shadow:0 0 8px #ef4444;animation:lb 1.2s ease-in-out infinite}\n@keyframes lb{0%,100%{opacity:1}50%{opacity:.3}}\n.cc-class{font-size:12px;font-weight:600;color:rgba(255,255,255,0.4);padding:4px 12px;background:rgba(255,255,255,0.07);border-radius:20px;border:1px solid rgba(255,255,255,0.1)}\n.cc-timer{font-size:14px;font-weight:800;letter-spacing:.04em;transition:color .3s}\n.cc-body{display:grid;grid-template-columns:1fr 1fr;min-height:300px}\n.cc-left{padding:26px 28px;border-right:1px solid rgba(255,255,255,0.07)}\n.cc-q-meta{font-size:10px;font-weight:700;color:rgba(255,255,255,0.22);letter-spacing:.1em;text-transform:uppercase;margin-bottom:12px}\n.cc-q-text{font-size:18px;font-weight:700;color:#e2e8f0;line-height:1.4;margin-bottom:22px;min-height:54px;transition:opacity .3s}\n.choices{display:flex;flex-direction:column;gap:8px}\n.choice{padding:11px 15px;border-radius:11px;border:1px solid rgba(255,255,255,0.08);background:rgba(255,255,255,0.04);font-size:13px;font-weight:500;color:rgba(255,255,255,0.65);display:flex;align-items:center;gap:11px;position:relative;overflow:hidden;transition:all .4s}\n.choice.correct{border-color:rgba(16,185,129,0.4);background:rgba(16,185,129,0.08);color:#34d399}\n.choice.correct::before{content:'';position:absolute;left:0;top:0;bottom:0;width:3px;background:#10b981;box-shadow:0 0 10px #10b981}\n.choice.wrong{border-color:rgba(239,68,68,0.22);background:rgba(239,68,68,0.05);color:rgba(255,255,255,0.3)}\n.ch-letter{width:24px;height:24px;border-radius:7px;background:rgba(255,255,255,0.07);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800;flex-shrink:0;transition:all .4s}\n.choice.correct .ch-letter{background:rgba(16,185,129,0.22);color:#34d399}\n.choice.wrong .ch-letter{background:rgba(239,68,68,0.14);color:#f87171}\n.ch-pct{margin-left:auto;font-size:10px;font-weight:700;opacity:0;transition:opacity .6s .3s}\n.choice.reveal .ch-pct{opacity:1}\n.ch-bar{position:absolute;left:0;top:0;bottom:0;width:0%;pointer-events:none;transition:width 1s cubic-bezier(.23,1,.32,1) .2s}\n.cc-right{padding:24px;overflow:hidden}\n.cc-r-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}\n.cc-r-lbl{font-size:10px;font-weight:700;color:rgba(255,255,255,0.22);text-transform:uppercase;letter-spacing:.09em}\n.cc-r-cnt{font-size:13px;font-weight:800;color:#60a5fa}\n.s-feed{display:flex;flex-direction:column;gap:7px;max-height:250px;overflow:hidden}\n.s-row{display:flex;align-items:center;gap:10px;padding:8px 12px;border-radius:10px;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.06);animation:si .4s cubic-bezier(.23,1,.32,1) both}\n@keyframes si{from{opacity:0;transform:translateX(16px)}to{opacity:1;transform:none}}\n.s-av{width:27px;height:27px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;flex-shrink:0}\n.s-nm{font-size:12px;font-weight:600;color:rgba(255,255,255,0.7);flex:1}\n.s-sc{font-size:12px;font-weight:800}\n.s-tk{width:18px;height:18px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-shrink:0}\n.cc-progress{padding:14px 20px;border-top:1px solid rgba(255,255,255,0.07);display:grid;grid-template-columns:repeat(4,1fr);gap:10px;background:rgba(0,0,0,0.2)}\n.resp-col{text-align:center}\n.resp-lbl{font-size:9px;font-weight:700;color:rgba(255,255,255,0.28);text-transform:uppercase;letter-spacing:.07em;margin-bottom:5px}\n.resp-track{height:28px;background:rgba(255,255,255,0.06);border-radius:4px;overflow:hidden;display:flex;align-items:flex-end}\n.resp-fill{width:100%;border-radius:4px 4px 0 0;transition:height 1.2s cubic-bezier(.23,1,.32,1)}\n.resp-num{font-size:10px;font-weight:700;margin-top:4px}\n.q-dots{display:flex;gap:6px;justify-content:center;margin-bottom:24px}\n.q-dot{width:8px;height:8px;border-radius:50%;background:rgba(255,255,255,0.15);transition:all .4s;cursor:default}\n.q-dot.active{background:#6366f1;box-shadow:0 0 10px #6366f1;width:24px;border-radius:4px}\n.q-dot.done{background:rgba(16,185,129,0.7)}\n\n/* \u2550\u2550 TEACHER ANALYTICS \u2550\u2550 */\n.an-card{background:rgba(8,12,22,0.88);border:1px solid rgba(255,255,255,0.1);border-radius:20px;overflow:hidden;box-shadow:0 40px 100px rgba(0,0,0,.6);backdrop-filter:blur(24px);max-width:1000px;margin:0 auto}\n.an-top{padding:16px 24px;border-bottom:1px solid rgba(255,255,255,0.07);display:flex;align-items:center;justify-content:space-between;background:rgba(255,255,255,0.03)}\n.an-title{font-size:14px;font-weight:700;color:#e2e8f0}\n.an-sub-txt{font-size:12px;color:rgba(255,255,255,0.3)}\n.done-badge{display:flex;align-items:center;gap:6px;padding:5px 12px;border-radius:20px;background:rgba(16,185,129,0.1);border:1px solid rgba(16,185,129,0.25);font-size:11px;font-weight:700;color:#34d399}\n.an-body{display:grid;grid-template-columns:1fr 1fr}\n.an-left{padding:22px;border-right:1px solid rgba(255,255,255,0.07)}\n.an-right{padding:22px}\n.an-sec{font-size:10px;font-weight:700;color:rgba(255,255,255,0.22);text-transform:uppercase;letter-spacing:.09em;margin-bottom:14px}\n.topic-row{display:flex;align-items:center;gap:12px;margin-bottom:11px}\n.topic-nm{font-size:12px;font-weight:600;color:rgba(255,255,255,0.7);width:140px;flex-shrink:0}\n.topic-track{flex:1;height:8px;background:rgba(255,255,255,0.07);border-radius:4px;overflow:hidden}\n.topic-fill{height:100%;border-radius:4px;transition:width 1.8s cubic-bezier(.23,1,.32,1);width:0%}\n.topic-pct{font-size:11px;font-weight:700;min-width:32px;text-align:right}\n.st-an-row{display:flex;align-items:center;gap:10px;padding:9px 12px;border-radius:10px;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.07);margin-bottom:7px;animation:si .5s cubic-bezier(.23,1,.32,1) both}\n.st-info{flex:1;min-width:0}\n.st-nm2{font-size:12px;font-weight:600;color:rgba(255,255,255,0.8)}\n.st-sub2{font-size:10px;color:rgba(255,255,255,0.3);margin-top:1px}\n.st-flag{font-size:10px;padding:3px 8px;border-radius:5px;font-weight:700;white-space:nowrap}\n\n/* \u2550\u2550 NOVA SECTION \u2550\u2550 */\n/* LEFT: content \u2014 RIGHT: orb only, clean */\n.nova-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center;max-width:1200px;margin:0 auto}\n/* LEFT side */\n.nova-content{}\n.nova-feats{display:flex;flex-direction:column;gap:10px;margin-bottom:28px}\n.nf{display:flex;align-items:flex-start;gap:12px;padding:13px 17px;border-radius:13px;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.08);backdrop-filter:blur(12px);transition:all .2s;cursor:default}\n.nf:hover{background:rgba(255,255,255,0.07);border-color:rgba(255,255,255,0.13);transform:translateX(4px)}\n.nf-ico{width:34px;height:34px;border-radius:10px;display:flex;align-items:center;justify-content:center;flex-shrink:0}\n.nf-ico svg{width:15px;height:15px;fill:none;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}\n.nf-n{font-size:13px;font-weight:700;color:#e2e8f0;margin-bottom:2px}\n.nf-d{font-size:11px;color:rgba(255,255,255,0.36);line-height:1.5}\n\n/* Horizontal chat demo \u2014 under the feature list */\n.chat-demo{background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.08);border-radius:14px;padding:16px;display:flex;flex-direction:column;gap:9px}\n.chat-demo-lbl{font-size:10px;font-weight:700;color:rgba(255,255,255,0.2);text-transform:uppercase;letter-spacing:.09em;margin-bottom:4px}\n.cd-row{display:flex;gap:8px;align-items:flex-end}\n.cd-row.right{flex-direction:row-reverse}\n.cd-av{width:24px;height:24px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700}\n.cd-bub{padding:9px 13px;border-radius:12px;font-size:12px;font-weight:500;line-height:1.45;max-width:80%}\n.cd-bub.nova-bub{background:rgba(255,255,255,0.07);border:1px solid rgba(255,255,255,0.1);color:rgba(255,255,255,0.75);border-bottom-left-radius:4px}\n.cd-bub.user-bub{background:rgba(99,102,241,0.18);border:1px solid rgba(99,102,241,0.28);color:rgba(255,255,255,0.9);border-bottom-right-radius:4px}\n\n/* RIGHT: orb \u2014 completely clean, no bubbles on it */\n.nova-orb-wrap{display:flex;align-items:center;justify-content:center;position:relative;height:400px}\n.nova-orb{width:180px;height:180px;border-radius:50%;background:radial-gradient(circle at 33% 33%,#c4b5fd,#7c3aed 40%,#4c1d95 70%,#08001a);box-shadow:0 0 55px rgba(124,58,237,0.7),0 0 120px rgba(109,40,217,0.4),0 0 220px rgba(99,102,241,0.18),inset 0 0 45px rgba(196,181,253,0.2);animation:orb-b 3.5s ease-in-out infinite;position:relative;z-index:2}\n@keyframes orb-b{0%,100%{box-shadow:0 0 55px rgba(124,58,237,0.7),0 0 120px rgba(109,40,217,0.4),0 0 220px rgba(99,102,241,0.18),inset 0 0 45px rgba(196,181,253,0.2);transform:scale(1)}50%{box-shadow:0 0 80px rgba(124,58,237,0.9),0 0 170px rgba(109,40,217,0.55),0 0 300px rgba(99,102,241,0.28),inset 0 0 65px rgba(196,181,253,0.32);transform:scale(1.05)}}\n.nova-gloss{position:absolute;top:18%;left:23%;width:52%;height:37%;background:radial-gradient(ellipse at 42% 42%,rgba(255,255,255,0.26),transparent 70%);border-radius:50%;z-index:3;pointer-events:none}\n.orb-ring{position:absolute;top:50%;left:50%;border-radius:50%;border-style:solid;animation:rorbit linear infinite;transform-origin:center}\n@keyframes rorbit{from{transform:translate(-50%,-50%) rotate(0deg)}to{transform:translate(-50%,-50%) rotate(360deg)}}\n.orb-ring::before{content:'';position:absolute;top:0;left:50%;transform:translate(-50%,-50%);border-radius:50%}\n.r1{width:260px;height:260px;border-width:1px;border-color:rgba(129,140,248,0.22);animation-duration:9s}\n.r1::before{width:8px;height:8px;background:#818cf8;box-shadow:0 0 12px #818cf8,0 0 24px rgba(129,140,248,0.5)}\n.r2{width:340px;height:340px;border-width:1px;border-color:rgba(167,139,250,0.14);animation-duration:14s;animation-direction:reverse}\n.r2::before{width:6px;height:6px;background:#a78bfa;box-shadow:0 0 10px #a78bfa}\n.r2::after{content:'';position:absolute;bottom:0;left:50%;transform:translate(-50%,50%);width:4px;height:4px;border-radius:50%;background:#6366f1;box-shadow:0 0 8px #6366f1}\n.r3{width:390px;height:390px;border-width:1px;border-color:rgba(99,102,241,0.08);animation-duration:21s}\n.r3::before{width:5px;height:5px;background:#c4b5fd;box-shadow:0 0 8px #c4b5fd}\n\n/* \u2550\u2550 FLASHCARD SECTION \u2550\u2550 */\n.fc-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center;max-width:1200px;margin:0 auto}\n/* FIXED: explicit height instead of aspect-ratio so card-face inset:0 works */\n.card-scene{perspective:800px;width:100%;max-width:420px;margin:0 auto}\n.card-3d{\n  width:100%;\n  height:240px;\n  position:relative;\n  cursor:pointer;\n  /* NO preserve-3d \u2014 each face animates independently via opacity + rotateY */\n}\n.card-face{\n  position:absolute;\n  inset:0;\n  border-radius:20px;padding:26px;\n  display:flex;flex-direction:column;\n  overflow:hidden;\n  transform-origin:center center;\n}\n/* FRONT: visible by default, rotates to 90\u00b0 (edge-on/invisible) when flipped */\n.cf-front{\n  background:linear-gradient(145deg,#16112e,#100c22);\n  border:1px solid rgba(129,140,248,0.32);\n  box-shadow:inset 0 0 0 1px rgba(129,140,248,0.1),0 24px 70px rgba(0,0,0,.6),0 0 90px rgba(99,102,241,0.1);\n  transform:rotateY(0deg);\n  opacity:1;\n  transition:transform .3s ease-out .3s, opacity 0s .3s;\n  z-index:2;\n}\n.cf-front::before{content:'';position:absolute;top:-50px;right:-50px;width:200px;height:200px;background:radial-gradient(circle,rgba(99,102,241,0.22),transparent 65%);pointer-events:none}\n\n/* BACK: starts rotated away, comes in after front disappears */\n.cf-back{\n  background:linear-gradient(145deg,#0a1a12,#081410);\n  border:1px solid rgba(52,211,153,0.32);\n  box-shadow:inset 0 0 0 1px rgba(52,211,153,0.1),0 24px 70px rgba(0,0,0,.6),0 0 90px rgba(16,185,129,0.1);\n  transform:rotateY(-90deg);\n  opacity:0;\n  /* back waits for front to disappear at 0.26s, then animates in */\n  transition:transform .3s ease-in, opacity 0s .3s;\n  z-index:1;\n  justify-content:flex-start;gap:10px;\n}\n.cf-back::before{content:'';position:absolute;top:-50px;right:-50px;width:200px;height:200px;background:radial-gradient(circle,rgba(16,185,129,0.18),transparent 65%);pointer-events:none}\n\n/* FLIPPED STATE \u2014 hover or .flipped class */\n.card-scene:hover .cf-front,\n.card-scene.flipped .cf-front{\n  transform:rotateY(90deg);  /* rotate to edge \u2014 invisible */\n  opacity:0;\n  transition:transform .3s ease-in, opacity 0s .3s;\n  z-index:1;\n}\n.card-scene:hover .cf-back,\n.card-scene.flipped .cf-back{\n  transform:rotateY(0deg);   /* rotate from edge to flat \u2014 visible */\n  opacity:1;\n  transition:transform .3s ease-out .3s, opacity 0s .3s;\n  z-index:2;\n}\n.cf-shine{position:absolute;inset:0;border-radius:20px;background:linear-gradient(135deg,rgba(255,255,255,0.06) 0%,transparent 50%);pointer-events:none;z-index:0}\n.cf-tag{display:inline-flex;align-items:center;gap:5px;font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;padding:4px 10px;border-radius:100px;align-self:flex-start;position:relative;z-index:1;margin-bottom:auto}\n.ftag{background:rgba(129,140,248,0.12);color:#818cf8;border:1px solid rgba(129,140,248,0.22)}\n.btag{background:rgba(52,211,153,0.1);color:#34d399;border:1px solid rgba(52,211,153,0.22)}\n.cf-subj{font-size:10px;font-weight:700;color:rgba(255,255,255,0.25);text-transform:uppercase;letter-spacing:.07em;margin-bottom:7px;position:relative;z-index:1}\n.cf-q{font-size:clamp(14px,2vw,17px);font-weight:700;color:#e2e8f0;line-height:1.38;position:relative;z-index:1}\n.cf-hint{font-size:11px;color:rgba(255,255,255,0.2);position:relative;z-index:1;margin-top:auto}\n.cf-ans-lbl{font-size:10px;font-weight:700;color:rgba(52,211,153,0.6);text-transform:uppercase;letter-spacing:.08em;position:relative;z-index:1;margin-top:6px}\n.cf-a{font-size:clamp(13px,1.8vw,16px);font-weight:600;color:#e2e8f0;line-height:1.5;position:relative;z-index:1}\n.card-dots{display:flex;gap:6px;justify-content:center;margin-top:14px}\n.cdot{width:6px;height:6px;border-radius:50%;background:rgba(255,255,255,0.15);transition:all .3s;cursor:pointer}\n.cdot.active{background:#818cf8;box-shadow:0 0 8px #818cf8;width:18px;border-radius:3px}\n\n/* SRS chart */\n.srs-wrap{padding:18px;border-radius:14px;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.08);margin-top:24px}\n.srs-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}\n.srs-t{font-size:12px;font-weight:700;color:rgba(255,255,255,0.4)}\n.srs-streak{font-size:12px;font-weight:700;color:#34d399;display:flex;align-items:center;gap:4px}\n.srs-bars{display:flex;flex-direction:column;gap:4px}\n.srs-bar-track{display:flex;gap:5px;align-items:flex-end;height:54px}\n.srs-label-row{display:flex;gap:5px}\n.srs-col{flex:1;display:flex;align-items:flex-end}\n.srs-bar{width:100%;border-radius:4px 4px 0 0;transition:height 1.3s cubic-bezier(.23,1,.32,1);position:relative}\n.srs-bar::after{content:'';position:absolute;inset:0;border-radius:inherit;background:linear-gradient(to top,transparent,rgba(255,255,255,0.1))}\n.srs-day{font-size:9px;color:rgba(255,255,255,0.2);font-weight:600}\n\n/* \u2550\u2550 PRICING \u2550\u2550 */\n.pricing-section{padding:100px 48px;position:relative}\n.pricing-section::before{content:'';position:absolute;inset:0;background:linear-gradient(180deg,transparent,rgba(8,10,20,0.5) 30%,rgba(8,10,20,0.5) 70%,transparent);pointer-events:none}\n.pricing-inner{max-width:860px;margin:0 auto;position:relative;z-index:1;text-align:center}\n/* Toggle */\n.billing-toggle{display:inline-flex;gap:2px;padding:4px;border-radius:100px;background:rgba(255,255,255,0.07);border:1px solid rgba(255,255,255,0.1);margin-bottom:50px}\n.btog{padding:7px 22px;border-radius:100px;font-size:13px;font-weight:600;cursor:pointer;transition:all .22s;color:rgba(255,255,255,0.45);display:flex;align-items:center;gap:6px}\n.btog.on{background:rgba(255,255,255,0.12);color:#e2e8f0;box-shadow:0 2px 8px rgba(0,0,0,.3)}\n/* Save pill \u2014 ALWAYS VISIBLE, just changes style */\n.save-pill{display:inline-flex;align-items:center;font-size:10px;font-weight:700;border-radius:100px;padding:2px 8px;vertical-align:middle;transition:all .3s;color:#6c7086;background:rgba(255,255,255,0.08);border:1px solid rgba(255,255,255,0.1)}\n.save-pill.bright{color:#34d399;background:rgba(16,185,129,0.12);border-color:rgba(16,185,129,0.25)}\n\n.pricing-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;max-width:680px;margin:0 auto}\n.pc{border-radius:22px;padding:30px 26px;position:relative;overflow:hidden;backdrop-filter:blur(24px);transition:transform .2s}\n.pc:hover{transform:translateY(-4px)}\n.pc-s{background:linear-gradient(145deg,rgba(37,99,235,0.18),rgba(124,58,237,0.14));border:1px solid rgba(99,102,241,0.4);box-shadow:0 0 80px rgba(99,102,241,0.1)}\n.pc-s::before{content:'';position:absolute;top:-1px;left:0;right:0;height:2px;background:linear-gradient(90deg,transparent,#6366f1,#a78bfa,transparent)}\n.pc-t{background:rgba(245,158,11,0.05);border:1px solid rgba(245,158,11,0.2)}\n.pc-t::before{content:'';position:absolute;top:-1px;left:0;right:0;height:2px;background:linear-gradient(90deg,transparent,#f59e0b,#fbbf24,transparent)}\n.pop-badge{position:absolute;top:14px;right:14px;background:linear-gradient(135deg,#6366f1,#8b5cf6);color:#fff;font-size:9px;font-weight:800;padding:3px 10px;border-radius:100px;letter-spacing:.06em;text-transform:uppercase}\n.pc-tier{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;padding:4px 12px;border-radius:100px;display:inline-block;margin-bottom:18px}\n.pc-s .pc-tier{background:rgba(99,102,241,0.2);color:#a5b4fc;border:1px solid rgba(99,102,241,0.3)}\n.pc-t .pc-tier{background:rgba(245,158,11,0.12);color:#fbbf24;border:1px solid rgba(245,158,11,0.25)}\n.pc-price-row{display:flex;align-items:flex-end;gap:4px;margin-bottom:4px}\n.pc-amt{font-size:48px;font-weight:900;letter-spacing:-2px;color:#e2e8f0;line-height:1;transition:all .3s}\n.pc-per{font-size:14px;color:rgba(255,255,255,0.3);margin-bottom:10px}\n.pc-note{font-size:11px;color:rgba(255,255,255,0.25);margin-bottom:14px;min-height:16px;transition:all .3s}\n.pc-desc{font-size:13px;color:rgba(255,255,255,0.35);line-height:1.6;margin-bottom:20px;min-height:48px}\n.pc-div{height:1px;background:rgba(255,255,255,0.07);margin-bottom:18px}\n.pc-feats{list-style:none;display:flex;flex-direction:column;gap:9px;margin-bottom:24px;text-align:left}\n.pc-feats li{display:flex;align-items:center;gap:9px;font-size:13px;color:rgba(255,255,255,0.6)}\n.pc-chk{width:16px;height:16px;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-shrink:0}\n.pc-s .pc-chk{background:rgba(99,102,241,0.25)}.pc-t .pc-chk{background:rgba(245,158,11,0.2)}\n.pc-btn{width:100%;padding:13px;border-radius:12px;border:none;font-size:14px;font-weight:700;cursor:pointer;font-family:inherit;transition:all .15s}\n.pc-s .pc-btn{background:linear-gradient(135deg,#2563eb,#7c3aed);color:#fff;box-shadow:0 8px 24px rgba(99,102,241,0.45)}\n.pc-s .pc-btn:hover{box-shadow:0 12px 32px rgba(99,102,241,0.6)}\n.pc-t .pc-btn{background:rgba(245,158,11,0.12);border:1px solid rgba(245,158,11,0.28);color:#fbbf24}\n.pc-t .pc-btn:hover{background:rgba(245,158,11,0.2)}\n.pricing-links{display:flex;gap:20px;justify-content:center;margin-top:28px;flex-wrap:wrap}\n.pricing-links a{font-size:13px;color:rgba(255,255,255,0.3);text-decoration:none;transition:color .2s}\n.pricing-links a:hover{color:rgba(255,255,255,0.65)}\n\n/* \u2550\u2550 CTA \u2550\u2550 */\n.cta-section{padding:120px 48px 140px;text-align:center;position:relative;overflow:visible}\n.cta-section::before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at 30% 50%,rgba(99,102,241,0.09),transparent 60%),radial-gradient(ellipse at 70% 50%,rgba(236,72,153,0.07),transparent 60%);pointer-events:none}\n.cta-inner{max-width:680px;margin:0 auto;position:relative;z-index:1}\n/* FIX: padding-bottom on gradient-clipped CTA title for \"y\" descender */\n.cta-title{\n  font-size:clamp(36px,5.5vw,66px);\n  font-weight:900;letter-spacing:-.04em;line-height:1.12;\n  margin-bottom:20px;\n  padding-bottom:0.25em;\n  overflow:visible;\n  background:linear-gradient(135deg,#fff 0%,#e2e8f0 40%,#a5b4fc 80%);\n  -webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;\n}\n.cta-sub{font-size:18px;color:rgba(255,255,255,0.38);line-height:1.65;margin-bottom:44px}\n.cta-btns{display:flex;gap:14px;justify-content:center}\n\n/* \u2550\u2550 FOOTER \u2550\u2550 */\nfooter{padding:52px 48px 44px;border-top:1px solid rgba(255,255,255,0.06);background:rgba(5,7,9,0.55);backdrop-filter:blur(12px)}\n.footer-inner{max-width:1200px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:20px}\n.footer-logo{display:flex;align-items:center}\n.footer-wordmark{font-size:17px;font-weight:800;color:#e2e8f0;letter-spacing:-.02em}\n.footer-links{display:flex;gap:24px;flex-wrap:wrap}\n.footer-links a{font-size:13px;color:rgba(255,255,255,0.3);text-decoration:none;transition:color .2s}\n.footer-links a:hover{color:rgba(255,255,255,0.65)}\n.footer-copy{font-size:12px;color:rgba(255,255,255,0.18)}\n\n/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n   MOBILE \u2014 max-width: 768px\n   All 2-col grids collapse, paddings shrink,\n   hero wraps, nav hides links for hamburger\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\n@media (max-width: 768px) {\n\n  /* \u2500\u2500 Nav \u2500\u2500 */\n  nav { padding: 12px 20px; }\n  .nav-links { display: none; }\n  .btn-ghost { display: none; }\n  /* Show hamburger */\n  .btn-nav-cta { font-size: 13px; padding: 8px 16px; }\n\n  /* \u2500\u2500 Hero \u2500\u2500 */\n  .hero { padding: 100px 20px 70px; }\n  .hero-title {\n    font-size: clamp(38px, 11vw, 58px);\n    letter-spacing: -0.035em;\n    line-height: 1.1;\n    padding-bottom: 0.4em; /* fix y/g descender clip */\n  }\n  .hero-line { white-space: normal; } /* allow wrapping on small screens */\n  .hero-sub { font-size: 16px; }\n  .hero-btns { flex-direction: column; align-items: center; gap: 10px; }\n  .btn-primary { width: 100%; max-width: 320px; justify-content: center; padding: 14px 24px; font-size: 15px; }\n  .btn-sec { width: 100%; max-width: 320px; justify-content: center; padding: 14px 24px; font-size: 15px; }\n\n  /* \u2500\u2500 Sections \u2500\u2500 */\n  .sec-wrap { padding: 60px 20px; }\n  .sec-title { font-size: clamp(26px, 7vw, 40px); }\n  .sec-body { font-size: 15px; max-width: 100%; }\n  .sec-body-c { font-size: 15px; }\n  .eyebrow { justify-content: center; }\n\n  /* \u2500\u2500 Live Classroom \u2500\u2500 */\n  .cc-card { border-radius: 14px; }\n  .cc-body { grid-template-columns: 1fr; }\n  /* Hide student feed on mobile \u2014 card would be illegible at 2-col */\n  .cc-right { display: none; }\n  /* Smaller question text */\n  .cc-q-text { font-size: 15px; }\n  .cc-progress { grid-template-columns: repeat(2, 1fr); gap: 8px; padding: 12px 14px; }\n  .cc-left { padding: 20px; }\n\n  /* \u2500\u2500 Teacher Analytics \u2500\u2500 */\n  .an-body { grid-template-columns: 1fr; }\n  .an-left { border-right: none; border-bottom: 1px solid rgba(255,255,255,0.07); }\n  .an-right { padding-top: 16px; }\n  .an-card { border-radius: 14px; }\n\n  /* \u2500\u2500 Nova \u2500\u2500 */\n  .nova-grid {\n    grid-template-columns: 1fr;\n    gap: 48px;\n  }\n  /* On mobile: orb first, content below */\n  .nova-grid > div:first-child { order: 1; }\n  .nova-content { order: 2; }\n  .nova-orb-wrap { height: 280px; }\n  .nova-orb { width: 130px; height: 130px; }\n  .r1 { width: 190px; height: 190px; }\n  .r2 { width: 250px; height: 250px; }\n  .r3 { width: 300px; height: 300px; }\n  .chat-demo { display: none; } /* hide chat demo on mobile \u2014 save space */\n  .nova-feats { gap: 8px; }\n  .sec-body { margin-bottom: 24px; }\n\n  /* \u2500\u2500 Flashcards \u2500\u2500 */\n  .fc-grid {\n    grid-template-columns: 1fr;\n    gap: 36px;\n  }\n  .card-scene { max-width: 100%; }\n  .card-3d { height: 220px; }\n  .srs-wrap { margin-top: 0; }\n\n  /* \u2500\u2500 Pricing \u2500\u2500 */\n  .pricing-section { padding: 60px 20px; }\n  .pricing-grid {\n    grid-template-columns: 1fr;\n    max-width: 360px;\n    gap: 16px;\n  }\n  .pc-s { transform: none !important; } /* remove scale on mobile */\n  .pc-s:hover { transform: translateY(-4px) !important; }\n  .pricing-links { flex-direction: column; align-items: center; gap: 10px; }\n  .billing-toggle { margin-bottom: 36px; }\n\n  /* \u2500\u2500 CTA \u2500\u2500 */\n  .cta-section { padding: 80px 20px 120px; }\n  .cta-title { font-size: clamp(32px, 9vw, 52px); }\n  .cta-sub { font-size: 16px; }\n  .cta-btns { flex-direction: column; align-items: center; gap: 10px; }\n  .cta-btns .btn-primary { width: 100%; max-width: 320px; justify-content: center; font-size: 16px; padding: 16px 24px; }\n  .cta-btns .btn-sec { width: 100%; max-width: 320px; justify-content: center; font-size: 16px; padding: 16px 24px; }\n\n  /* \u2500\u2500 Footer \u2500\u2500 */\n  footer { padding: 40px 20px 36px; }\n  .footer-inner { flex-direction: column; align-items: center; text-align: center; gap: 20px; }\n  .footer-links { justify-content: center; gap: 16px; }\n\n  /* \u2500\u2500 Q dots \u2500\u2500 */\n  .q-dots { gap: 4px; }\n\n  /* \u2500\u2500 Scroll indicator \u2500\u2500 */\n  .scroll-ind { display: none; }\n\n}\n\n/* \u2500\u2500 Tiny phones \u2500\u2500 */\n@media (max-width: 390px) {\n  .hero-title { font-size: clamp(32px, 10vw, 48px); }\n  .hero-btns .btn-primary,\n  .hero-btns .btn-sec { max-width: 100%; }\n  nav { padding: 12px 16px; }\n  .logo-wordmark { font-size: 16px; }\n}\n\n\n/* \u2500\u2500 Hamburger \u2500\u2500 */\n.hamburger{display:none;flex-direction:column;gap:5px;cursor:pointer;background:none;border:none;padding:6px;z-index:200}\n.hb-line{width:22px;height:2px;background:rgba(255,255,255,0.7);border-radius:1px;transition:all .3s;display:block}\n.hamburger.open .hb-line:nth-child(1){transform:rotate(45deg) translate(5px,5px)}\n.hamburger.open .hb-line:nth-child(2){opacity:0;transform:scaleX(0)}\n.hamburger.open .hb-line:nth-child(3){transform:rotate(-45deg) translate(5px,-5px)}\n.mob-menu{display:none;position:fixed;top:64px;left:0;right:0;background:rgba(5,7,9,0.97);backdrop-filter:blur(24px);border-bottom:1px solid rgba(255,255,255,0.08);padding:20px 24px;flex-direction:column;gap:4px;z-index:99}\n.mob-menu.open{display:flex}\n.mob-menu a{font-size:16px;font-weight:600;color:rgba(255,255,255,0.7);text-decoration:none;padding:12px 0;border-bottom:1px solid rgba(255,255,255,0.06);transition:color .2s}\n.mob-menu a:last-child{border-bottom:none}\n.mob-menu a:hover{color:#e2e8f0}\n.mob-menu .mob-cta{margin-top:12px;padding:14px;border-radius:12px;border:none;cursor:pointer;font-family:inherit;font-size:15px;font-weight:700;color:#fff;background:linear-gradient(135deg,#2563eb,#7c3aed);text-align:center}\n@media(max-width:768px){\n  .hamburger{display:flex}\n  .btn-ghost{display:none!important}\n  .nav-links{display:none!important}\n}\n"

const LP_JS = "// \u2550\u2550 WEBGL FLUID \u2550\u2550\n(function(){\n  const c=document.getElementById('bg'),gl=c.getContext('webgl')||c.getContext('experimental-webgl');\n  if(!gl)return;\n  function resize(){c.width=innerWidth;c.height=innerHeight;gl.viewport(0,0,c.width,c.height);}\n  resize();window.addEventListener('resize',resize);\n  const VS=`attribute vec2 aP;varying vec2 vU;void main(){vU=aP*.5+.5;gl_Position=vec4(aP,.999,1.);}`;\n  const FS=`precision highp float;uniform float uT;uniform vec2 uM,uR;uniform float uS;varying vec2 vU;\n  vec2 h2(vec2 p){p=vec2(dot(p,vec2(127.1,311.7)),dot(p,vec2(269.5,183.3)));return -1.+2.*fract(sin(p)*43758.545);}\n  float n(vec2 p){vec2 i=floor(p),f=fract(p),u=f*f*f*(f*(f*6.-15.)+10.);return mix(mix(dot(h2(i),f),dot(h2(i+vec2(1,0)),f-vec2(1,0)),u.x),mix(dot(h2(i+vec2(0,1)),f-vec2(0,1)),dot(h2(i+vec2(1,1)),f-vec2(1,1)),u.x),u.y);}\n  float fbm(vec2 p){float f=0.,a=.5,t=0.;mat2 r=mat2(.8,-.6,.6,.8);for(int i=0;i<6;i++){f+=a*n(p);t+=a;p=r*p*2.01;a*=.52;}return f/t;}\n  void main(){vec2 uv=vU;float ar=uR.x/uR.y;uv.x*=ar;float t=uT*.08;vec2 m=uM;m.x*=ar;float md=length(uv-m);uv+=(m-uv)/(md*md+.08)*.024;\n  vec2 q=vec2(fbm(uv*1.7+t*.9),fbm(uv*1.7+vec2(5.2,1.3)+t*.74));vec2 r=vec2(fbm(uv*1.7+3.4*q+vec2(1.7,9.2)+t*.58),fbm(uv*1.7+3.4*q+vec2(8.3,2.8)+t*.42));float f=fbm(uv*1.7+3.4*r+t*.32);f+=uS*.12;f=clamp(f,0.,1.);\n  vec3 col=mix(vec3(.010,.018,.10),vec3(.12,.022,.28),smoothstep(0.,.47,f));col=mix(col,vec3(.30,.06,.60),smoothstep(.27,.67,f));col=mix(col,vec3(.68,.12,.88),smoothstep(.51,.83,f));col=mix(col,vec3(.96,.28,.55),smoothstep(.74,1.,f));\n  col+=vec3(.28,.06,.50)*exp(-md*2.0)*.8;vec2 vig=vU-.5;col*=clamp(1.-dot(vig,vig)*1.55,.0,1.);col+=.014;gl_FragColor=vec4(col,1.);}`;\n  function mkS(t,s){const sh=gl.createShader(t);gl.shaderSource(sh,s);gl.compileShader(sh);return sh;}\n  const prog=gl.createProgram();gl.attachShader(prog,mkS(gl.VERTEX_SHADER,VS));gl.attachShader(prog,mkS(gl.FRAGMENT_SHADER,FS));gl.linkProgram(prog);\n  const buf=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buf);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);\n  const uT=gl.getUniformLocation(prog,'uT'),uM=gl.getUniformLocation(prog,'uM'),uR=gl.getUniformLocation(prog,'uR'),uS=gl.getUniformLocation(prog,'uS'),aP=gl.getAttribLocation(prog,'aP');\n  const mouse={x:.5,y:.5,tx:.5,ty:.5};\n  window.addEventListener('mousemove',e=>{mouse.tx=e.clientX/innerWidth;mouse.ty=1-e.clientY/innerHeight;const L=document.getElementById('heroLight');if(L){L.style.left=e.clientX+'px';L.style.top=e.clientY+'px';}});\n  let scroll=0;window.addEventListener('scroll',()=>{scroll=window.scrollY/(document.body.scrollHeight-innerHeight||1);},{passive:true});\n  window._lpStop=false;let t=0;function draw(){if(window._lpStop)return;requestAnimationFrame(draw);t+=.012;mouse.x+=(mouse.tx-mouse.x)*.06;mouse.y+=(mouse.ty-mouse.y)*.06;gl.clearColor(.02,.03,.06,1);gl.clear(gl.COLOR_BUFFER_BIT);gl.useProgram(prog);gl.uniform1f(uT,t);gl.uniform2f(uM,mouse.x,mouse.y);gl.uniform2f(uR,c.width,c.height);gl.uniform1f(uS,scroll);gl.bindBuffer(gl.ARRAY_BUFFER,buf);gl.enableVertexAttribArray(aP);gl.vertexAttribPointer(aP,2,gl.FLOAT,false,0,0);gl.drawArrays(gl.TRIANGLE_STRIP,0,4);}draw();\n})();\n\n// \u2550\u2550 SCROLL REVEAL \u2550\u2550\nconst obs=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');obs.unobserve(e.target);}});},{threshold:0.1});\ndocument.querySelectorAll('.rv').forEach(el=>obs.observe(el));\n\n// \u2550\u2550 NAV \u2550\u2550\nwindow.addEventListener('scroll',()=>{document.getElementById('navbar').style.background=window.scrollY>60?'rgba(5,7,9,0.92)':'rgba(5,7,9,0.65)';},{passive:true});\n\n// \u2550\u2550 LIVE CLASSROOM \u2014 FIXED: transitioning flag prevents multi-fire \u2550\u2550\nconst QS=[\n  {subj:'AP Biology \u00b7 Period 3',q:'Which organelle produces ATP through cellular respiration?',ch:['Nucleus','Ribosome','Mitochondria','Golgi apparatus'],correct:2,resp:[8,4,75,13],\n   students:[{n:'Jamie L.',c:true,sc:420,bg:'rgba(99,102,241,0.2)',col:'#818cf8'},{n:'Maya K.',c:true,sc:390,bg:'rgba(16,185,129,0.16)',col:'#34d399'},{n:'Aidan T.',c:false,sc:350,bg:'rgba(239,68,68,0.14)',col:'#f87171'},{n:'Sofia R.',c:true,sc:410,bg:'rgba(59,130,246,0.18)',col:'#60a5fa'},{n:'Liam W.',c:true,sc:380,bg:'rgba(245,158,11,0.16)',col:'#fbbf24'}]},\n  {subj:'AP Biology \u00b7 Period 3',q:'What is the role of mRNA in protein synthesis?',ch:['Stores genetic info','Carries amino acids','Carries DNA instructions to ribosome','Forms ribosome structure'],correct:2,resp:[11,9,68,12],\n   students:[{n:'Devon S.',c:true,sc:430,bg:'rgba(52,211,153,0.15)',col:'#34d399'},{n:'Priya N.',c:false,sc:365,bg:'rgba(239,68,68,0.14)',col:'#f87171'},{n:'Marcus W.',c:true,sc:405,bg:'rgba(99,102,241,0.2)',col:'#818cf8'},{n:'Emma L.',c:true,sc:415,bg:'rgba(59,130,246,0.18)',col:'#60a5fa'},{n:'Tyler D.',c:false,sc:340,bg:'rgba(239,68,68,0.14)',col:'#f87171'}]},\n  {subj:'AP Biology \u00b7 Period 3',q:'Which process converts glucose into pyruvate?',ch:['Krebs cycle','Glycolysis','Electron transport chain','Fermentation'],correct:1,resp:[7,72,14,7],\n   students:[{n:'Jamie L.',c:true,sc:420,bg:'rgba(99,102,241,0.2)',col:'#818cf8'},{n:'Sofia R.',c:true,sc:410,bg:'rgba(59,130,246,0.18)',col:'#60a5fa'},{n:'Aidan T.',c:true,sc:395,bg:'rgba(16,185,129,0.16)',col:'#34d399'},{n:'Priya N.',c:false,sc:360,bg:'rgba(239,68,68,0.14)',col:'#f87171'},{n:'Devon S.',c:true,sc:440,bg:'rgba(52,211,153,0.15)',col:'#34d399'}]}\n];\n\nlet curQ=0,tv=20,answered=0,si=0;\nlet transitioning=false; // FIX: prevents multiple nextQ calls during transition\n\nconst feed=document.getElementById('s-feed');\n\nfunction renderQ(qi,reveal){\n  const Q=QS[qi];\n  document.getElementById('cc-meta').textContent=`Question ${qi+1} of ${QS.length}`;\n  document.getElementById('cc-q').textContent=Q.q;\n  document.getElementById('cc-class').textContent=Q.subj;\n  // Choices\n  const ch=document.getElementById('cc-choices');ch.innerHTML='';\n  Q.ch.forEach((label,i)=>{\n    const d=document.createElement('div');\n    d.className='choice'+(reveal?i===Q.correct?' correct':' wrong':'');\n    if(reveal)d.classList.add('reveal');\n    const bar=document.createElement('div');bar.className='ch-bar';\n    bar.style.background=i===Q.correct?'rgba(16,185,129,0.1)':'rgba(239,68,68,0.06)';\n    if(reveal)setTimeout(()=>bar.style.width=Q.resp[i]+'%',200);\n    d.innerHTML=`<div class=\"ch-letter\">${String.fromCharCode(65+i)}</div>${label}<span class=\"ch-pct\" style=\"color:${i===Q.correct?'#34d399':'#f87171'}\">${reveal?Q.resp[i]+'%':''}</span>`;\n    d.prepend(bar);ch.appendChild(d);\n  });\n  // Progress bar\n  const prog=document.getElementById('cc-prog');prog.innerHTML='';\n  Q.ch.forEach((_,i)=>{\n    const col=document.createElement('div');col.className='resp-col';\n    const color=i===Q.correct?'#10b981':'rgba(239,68,68,0.45)';\n    const h=reveal?Math.round(Q.resp[i]*0.8)+'%':'6%';\n    const pct=reveal?Q.resp[i]+'%':'\u2014';\n    col.innerHTML=`<div class=\"resp-lbl\">${String.fromCharCode(65+i)}</div><div class=\"resp-track\"><div class=\"resp-fill\" style=\"height:${h};background:${color}${i===Q.correct?';box-shadow:0 0 10px rgba(16,185,129,0.4)':''}\"></div></div><div class=\"resp-num\" style=\"color:${i===Q.correct?'#34d399':'#f87171'}\">${pct}</div>`;\n    prog.appendChild(col);\n  });\n  // Dots\n  document.querySelectorAll('.q-dot').forEach((d,i)=>{d.classList.remove('active','done');if(i===qi)d.classList.add('active');else if(i<qi)d.classList.add('done');});\n}\n\nfunction addStudent(){\n  const Q=QS[curQ];if(si>=Q.students.length)si=0;\n  const s=Q.students[si++];answered++;\n  document.getElementById('cc-cnt').textContent=answered+' answered';\n  const row=document.createElement('div');row.className='s-row';\n  row.innerHTML=`<div class=\"s-av\" style=\"background:${s.bg};color:${s.col}\">${s.n.split(' ').map(x=>x[0]).join('')}</div><div class=\"s-nm\">${s.n}</div><div class=\"s-sc\" style=\"color:${s.c?'#34d399':'#f87171'}\">${s.sc}</div><div class=\"s-tk\" style=\"background:${s.c?'rgba(16,185,129,0.2)':'rgba(239,68,68,0.15)'}\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"${s.c?'#34d399':'#f87171'}\" stroke-width=\"2.5\" stroke-linecap=\"round\">${s.c?'<path d=\"M2 8l4 4 8-8\"/>':'<path d=\"M3 3l10 10M13 3L3 13\"/>'}</svg></div>`;\n  feed.appendChild(row);while(feed.children.length>6)feed.removeChild(feed.firstChild);\n}\n\nfunction nextQ(){\n  if(transitioning)return; // FIX: block re-entry\n  transitioning=true;\n  tv=-1; // FIX: stop timer immediately so it can't fire nextQ again\n  renderQ(curQ,true);\n  // Animate bar heights after reveal\n  setTimeout(()=>{\n    document.querySelectorAll('#cc-prog .resp-fill').forEach((f,i)=>{\n      setTimeout(()=>f.style.height=Math.round(QS[curQ].resp[i]*0.8)+'%',i*60);\n    });\n  },100);\n  // Transition to next after 3.5s\n  setTimeout(()=>{\n    curQ=(curQ+1)%QS.length;\n    tv=20;answered=0;si=0;\n    feed.innerHTML='';\n    renderQ(curQ,false);\n    transitioning=false; // FIX: unlock after transition completes\n  },3500);\n}\n\n// Timer interval \u2014 checks transitioning flag\nsetInterval(()=>{\n  if(transitioning)return; // FIX: do nothing while transitioning\n  if(tv<=0)return;\n  tv=Math.max(0,tv-1);\n  const te=document.getElementById('cc-timer');\n  te.textContent='0:'+(tv<10?'0':'')+tv;\n  te.style.color=tv<6?'#f87171':'#fbbf24';\n  if(tv===0)nextQ();\n},1000);\n\n// Student feed interval\nsetInterval(()=>{if(!transitioning)addStudent();},1900);\n\n// Init\nrenderQ(0,false);setTimeout(()=>addStudent(),700);\n\n// \u2550\u2550 TEACHER ANALYTICS \u2550\u2550\nconst TOPICS=[{nm:'Cellular Respiration',pct:72,col:'#34d399'},{nm:'Protein Synthesis',pct:58,col:'#fbbf24'},{nm:'Glycolysis',pct:83,col:'#34d399'},{nm:'Cell Division',pct:41,col:'#f87171'},{nm:'Photosynthesis',pct:66,col:'#fbbf24'}];\nconst STANS=[{nm:'Tyler D.',sub:'Needs help with Cell Division',col:'#f87171',flag:'Struggling',flagBg:'rgba(239,68,68,0.1)',delay:0},{nm:'Priya N.',sub:'Weak in Protein Synthesis',col:'#fbbf24',flag:'At risk',flagBg:'rgba(245,158,11,0.1)',delay:80},{nm:'Jamie L.',sub:'Excelling across all topics',col:'#34d399',flag:'Top performer',flagBg:'rgba(16,185,129,0.1)',delay:160},{nm:'Devon S.',sub:'Strong in Glycolysis',col:'#34d399',flag:'Excelling',flagBg:'rgba(16,185,129,0.1)',delay:240}];\nconst tbEl=document.getElementById('topic-bars');\nTOPICS.forEach(t=>{const r=document.createElement('div');r.className='topic-row';r.innerHTML=`<div class=\"topic-nm\">${t.nm}</div><div class=\"topic-track\"><div class=\"topic-fill\" style=\"background:${t.col}\" data-p=\"${t.pct}\"></div></div><div class=\"topic-pct\" style=\"color:${t.col}\">${t.pct}%</div>`;tbEl.appendChild(r);});\nconst sgEl=document.getElementById('st-grid');\nSTANS.forEach(s=>{const r=document.createElement('div');r.className='st-an-row';r.style.animationDelay=s.delay+'ms';const av=s.nm.split(' ').map(x=>x[0]).join('');r.innerHTML=`<div class=\"s-av\" style=\"background:${s.flagBg};color:${s.col};width:28px;height:28px\">${av}</div><div class=\"st-info\"><div class=\"st-nm2\">${s.nm}</div><div class=\"st-sub2\">${s.sub}</div></div><span class=\"st-flag\" style=\"color:${s.col};background:${s.flagBg};border:1px solid ${s.col}33\">${s.flag}</span>`;sgEl.appendChild(r);});\nnew IntersectionObserver(entries=>{if(entries[0].isIntersecting){document.querySelectorAll('.topic-fill').forEach((f,i)=>{setTimeout(()=>f.style.width=f.dataset.p+'%',i*130);});}},{threshold:0.4}).observe(tbEl);\n\n// \u2550\u2550 NOVA CHAT TYPING ANIMATION \u2550\u2550\nsetTimeout(()=>{\n  const typing=document.getElementById('nova-typing');\n  const reply=document.getElementById('nova-reply');\n  if(typing&&reply){typing.style.display='none';reply.style.display='block';}\n},2000);\n\n// \u2550\u2550 FLASHCARD DEMO \u2550\u2550\nconst CARDS=[\n  {subj:'Cell Biology',q:'What organelle produces ATP through cellular respiration?',a:'The mitochondria \u2014 the powerhouse of the cell, producing ATP through oxidative phosphorylation.'},\n  {subj:'US History',q:'What year did the American Civil War begin?',a:'1861 \u2014 Confederate forces attacked Fort Sumter in April, starting the deadliest conflict in US history.'},\n  {subj:'Physics',q:\"State Newton's Second Law of Motion.\",a:'F = ma \u2014 net force equals mass times acceleration. Force and acceleration share the same direction.'},\n  {subj:'Spanish',q:'Conjugate \"hablar\" for \"nosotros\" in present tense.',a:'\"Hablamos\" \u2014 we speak. Drop -ar, add -amos for nosotros in the present indicative.'},\n];\nlet ci=0;\nconst scene=document.getElementById('card-scene');\n\n// Build dots\nconst dotsEl=document.getElementById('card-dots');\nCARDS.forEach((_,i)=>{const d=document.createElement('div');d.className='cdot'+(i===0?' active':'');d.onclick=()=>setCard(i);dotsEl.appendChild(d);});\n\nfunction setCard(idx){\n  ci=idx;\n  document.getElementById('cf-subj').textContent=CARDS[ci].subj;\n  document.getElementById('cf-q').textContent=CARDS[ci].q;\n  document.getElementById('cf-a').textContent=CARDS[ci].a;\n  document.querySelectorAll('.cdot').forEach((d,i)=>d.classList.toggle('active',i===ci));\n}\n\n// Auto-cycle every 5s \u2014 only when card is not being hovered\nsetInterval(()=>{if(!scene.matches(':hover')){setCard((ci+1)%CARDS.length);}},5000);\n\n// Pure CSS hover handles the flip \u2014 no JS tilt that fights 3D\n// Just fade in the card outer wrapper via IntersectionObserver\nconst cardOuter=document.getElementById('card-outer');\nif(cardOuter){\n  new IntersectionObserver(entries=>{\n    if(entries[0].isIntersecting){cardOuter.style.opacity='1';} \n  },{threshold:0.1}).observe(cardOuter);\n}\n\n// \u2550\u2550 SRS BARS \u2550\u2550\nconst BD=[28,55,22,68,92,44,100],BC=['rgba(99,102,241,0.3)','rgba(99,102,241,0.4)','rgba(99,102,241,0.25)','rgba(99,102,241,0.5)','rgba(16,185,129,0.55)','rgba(99,102,241,0.35)','#10b981'],days=['M','T','W','T','F','S','S'];\nconst srsEl=document.getElementById('srs-bars');\nconst barTrack=document.createElement('div');barTrack.className='srs-bar-track';\nconst labelRow=document.createElement('div');labelRow.className='srs-label-row';\nBD.forEach((h,i)=>{\n  const col=document.createElement('div');col.className='srs-col';\n  const bar=document.createElement('div');bar.className='srs-bar';\n  bar.style.cssText=`width:100%;background:${BC[i]};height:0;transition:height 1.3s cubic-bezier(.23,1,.32,1) ${i*0.07}s`;\n  if(i===6)bar.style.boxShadow='0 0 14px rgba(16,185,129,0.5)';\n  col.appendChild(bar);barTrack.appendChild(col);\n  const lbl=document.createElement('div');lbl.className='srs-day';lbl.style.flex='1';lbl.style.textAlign='center';lbl.textContent=days[i];\n  labelRow.appendChild(lbl);\n  new IntersectionObserver(entries=>{if(entries[0].isIntersecting)bar.style.height=Math.round(h*0.54)+'px';},{threshold:.1}).observe(srsEl);\n});\nsrsEl.appendChild(barTrack);srsEl.appendChild(labelRow);\n\n// \u2550\u2550 PRICING TOGGLE \u2550\u2550\nfunction setBilling(mode){\n  const ann=mode==='annual';\n  document.getElementById('btog-mo').classList.toggle('on',!ann);\n  document.getElementById('btog-yr').classList.toggle('on',ann);\n  const pill=document.getElementById('save-pill');\n  // Always visible \u2014 just changes style\n  pill.classList.toggle('bright',ann);\n  document.getElementById('s-price').textContent=ann?'$55':'$7';\n  document.getElementById('s-note').textContent=ann?'$55 billed annually ($4.58/mo)':'Billed monthly';\n  document.getElementById('t-price').textContent=ann?'$99':'$13';\n  document.getElementById('t-note').textContent=ann?'$99 billed annually ($8.25/mo)':'Billed monthly';\n}\n\n// Hamburger menu\nvar hb=document.getElementById('hamburger'),mm=document.getElementById('mob-menu');\nif(hb&&mm){hb.addEventListener('click',function(){hb.classList.toggle('open');mm.classList.toggle('open');});}\n// Close menu on link click\nif(mm){mm.querySelectorAll('a').forEach(function(a){a.addEventListener('click',function(){hb.classList.remove('open');mm.classList.remove('open');});});}\n"

